/* one player's record in CardGameWork (stride 0x5C, fn_1_8EC8 initialises four) */
typedef struct CardPlayerWork_s {
    /* 0x00 */ s32 unk0;
    /* 0x04 */ s32 unk4;
    /* 0x08 */ s32 unk8;
    /* 0x0C */ s32 unkC;
    /* 0x10 */ s32 unk10; /* board x (fn_1_9C74 arg) */
    /* 0x14 */ s32 unk14; /* board y */
    /* 0x18 */ float unk18; /* facing angle: compared with 180/0/-90 (fn_1_30FA4) */
    /* 0x1C */ float unk1C;
    /* 0x20 */ s32 unk20;
    /* 0x24 */ s32 unk24;
    /* 0x28 */ s32 unk28;
    /* 0x2C */ s32 unk2C;
    /* 0x30 */ s32 unk30;
    /* 0x34 */ s32 unk34;
    /* 0x38 */ s32 unk38;
    /* 0x3C */ s32 unk3C;
    /* 0x40 */ s32 unk40;
    /* 0x44 */ s32 unk44;
    /* 0x48 */ s32 unk48;
    /* 0x4C */ s32 unk4C;
    /* 0x50 */ s32 unk50;
    /* 0x54 */ s16 unk54;
    /* 0x56 */ s16 unk56;
    /* 0x58 */ s16 unk58;
    /* 0x5A */ s16 unk5A; /* never accessed: tail padding of the 0x5C record */
} CardPlayerWork;

/* the game state, cardmain.c lbl_1_bss_E4 (0x1D8 bytes); passed as `work` to most functions */
typedef struct CardGameWork_s {
    /* 0x000 */ CardPlayerWork player[4];
    /* 0x170 */ s32 unk170; /* current turn: index into unk174 */
    /* 0x174 */ s32 unk174[4]; /* turn order: player[] index */
    /* 0x184 */ s32 unk184;
    /* 0x188 */ s32 unk188; /* state (0xC8..0xCE in fn_1_8B84) */
    /* 0x18C */ s32 unk18C; /* sub state (0x12C.. in fn_1_CA4) */
    /* 0x190 */ s32 unk190;
    /* 0x194 */ s32 unk194; /* board size (6.. in fn_1_30FA4) */
    /* 0x198 */ s32 unk198;
    /* 0x19C */ s32 unk19C; /* camera mode passed to fn_1_30FA4 */
    /* 0x1A0 */ s32 unk1A0;
    /* 0x1A4 */ s32 unk1A4;
    /* 0x1A8 */ s32 unk1A8;
    /* 0x1AC */ s32 unk1AC;
    /* 0x1B0 */ s32 unk1B0[3];
    /* 0x1BC */ s32 unk1BC;
    /* 0x1C0 */ s32 unk1C0;
    /* 0x1C4 */ s32 unk1C4;
    /* 0x1C8 */ s32 unk1C8;
    /* 0x1CC */ s32 unk1CC;
    /* 0x1D0 */ s32 unk1D0;
    /* 0x1D4 */ s32 unk1D4;
} CardGameWork;

/* status.c: a model record of the status scene (lbl_1_bss_1974..201C), 0x18 bytes */
typedef struct CardStatusMdl_s {
    /* 0x00 */ s16 mdlId;
    /* 0x02 */ s16 lightId;
    /* 0x04 */ s32 unk4;
    /* 0x08 */ s32 unk8;
    /* 0x0C */ HuVecF pos;
} CardStatusMdl;

/* status.c lbl_1_data_8D8: one entry per model group, 0x10 bytes */
typedef struct CardStatusMdlTbl_s {
    /* 0x00 */ s32 num;
    /* 0x04 */ s32 unk4;
    /* 0x08 */ s32 unk8;
    /* 0x0C */ CardStatusMdl *mdl;
} CardStatusMdlTbl;

